return {
  calculer: function(contexte) {
    if (typeof calculerShvedSupplyDemand === 'function') {
      return {
        donnees: calculerShvedSupplyDemand(contexte.bougies, contexte.parametres),
        primitives: calculerShvedSupplyDemand(contexte.bougies, contexte.parametres).primitives,
        typeSpecial: 'shved-supply-demand'
      };
    }
    const { bougies, parametres } = contexte;
    if (!bougies || bougies.length < 20) return { donnees: {}, primitives: { boites: [], lignes: [], labels: [] } };

    const supprimerZonesCassees = parametres.supprimerZonesCassees !== false;
    const afficherNonRetestees = Boolean(parametres.afficherNonRetestees);
    const afficherFaibles = Boolean(parametres.afficherFaibles);
    const minRetests = Math.max(0, parametres.minRetests !== undefined ? Number(parametres.minRetests) : (afficherNonRetestees ? 0 : 1));
    const zoneFuzzFactor = Number(parametres.zoneFuzzFactor || 0.75);
    const zoneExtend = parametres.zoneExtend !== false;
    const fastFactor = Math.max(2, Math.round(Number(parametres.fractalFastFactor || 3.0)));
    const slowFactor = Math.max(3, Math.round(Number(parametres.fractalSlowFactor || 6.0)));
    const zoneMerge = parametres.zoneMerge !== false;
    const maxHistorique = Number(parametres.maxLookbackBars || 800);
    const afficherZones = parametres.afficherZones !== false;
    const afficherLignes = parametres.afficherLignes !== false;
    const afficherEtiquettes = parametres.afficherEtiquettes !== false;

    const total = bougies.length;
    const atr = new Array(total).fill(0);
    const tr = new Array(total).fill(0);
    tr[0] = Math.max(0.0001, bougies[0].high - bougies[0].low);
    for (let i = 1; i < total; i++) {
      tr[i] = Math.max(bougies[i].high - bougies[i].low, Math.abs(bougies[i].high - bougies[i - 1].close), Math.abs(bougies[i].low - bougies[i - 1].close));
    }
    let somme = 0;
    const limite = Math.min(7, total);
    for (let i = 0; i < limite; i++) {
      somme += tr[i];
      atr[i] = somme / (i + 1);
    }
    for (let i = 7; i < total; i++) {
      atr[i] = (atr[i - 1] * 6 + tr[i]) / 7;
    }

    function estHaut(idx, p) {
      if (idx < p || idx >= total - p) return false;
      const ph = bougies[idx].high;
      for (let k = 1; k <= p; k++) {
        if (bougies[idx - k].high > ph || bougies[idx + k].high >= ph) return false;
      }
      return true;
    }

    function estBas(idx, p) {
      if (idx < p || idx >= total - p) return false;
      const pl = bougies[idx].low;
      for (let k = 1; k <= p; k++) {
        if (bougies[idx - k].low < pl || bougies[idx + k].low <= pl) return false;
      }
      return true;
    }

    const debut = Math.max(slowFactor, total - maxHistorique);
    const fin = total - fastFactor - 1;
    const candidates = [];

    for (let i = debut; i <= fin; i++) {
      const fu = ((atr[i] || (bougies[i].high - bougies[i].low)) / 2) * zoneFuzzFactor;

      if (estHaut(i, fastFactor)) {
        const estFaible = !estHaut(i, slowFactor);
        let hival = bougies[i].high + (zoneExtend ? fu : 0);
        let loval = Math.max(Math.min(bougies[i].close, bougies[i].high - fu), bougies[i].high - fu * 2);

        let hits = 0;
        let estCassee = false;
        let lastHit = i;
        let dateFin = bougies[total - 1].time;

        for (let k = i + 1; k < total; k++) {
          const b = bougies[k];
          if (b.high >= loval && b.low <= hival) {
            if (k - lastHit >= 6) {
              hits++;
              lastHit = k;
            }
          }
          if (b.close > hival) {
            estCassee = true;
            dateFin = b.time;
            break;
          }
        }

        if (estCassee && supprimerZonesCassees) continue;
        if (hits === 0 && !afficherNonRetestees) continue;
        if (estFaible && !afficherFaibles) continue;
        if (hits < minRetests) continue;

        const force = hits > 3 ? 'PROVEN' : (hits >= 1 ? 'VERIFIED' : (estFaible ? 'WEAK' : 'UNTESTED'));
        candidates.push({
          id: 'shved-res-' + i,
          type: 'RESISTANCE',
          prixHaut: hival,
          prixBas: loval,
          prixMedian: (hival + loval) / 2,
          retests: hits,
          force: force,
          dateDebut: bougies[i].time,
          dateFin: dateFin
        });
      }

      if (estBas(i, fastFactor)) {
        const estFaible = !estBas(i, slowFactor);
        let loval = bougies[i].low - (zoneExtend ? fu : 0);
        let hival = Math.min(Math.max(bougies[i].close, bougies[i].low + fu), bougies[i].low + fu * 2);

        let hits = 0;
        let estCassee = false;
        let lastHit = i;
        let dateFin = bougies[total - 1].time;

        for (let k = i + 1; k < total; k++) {
          const b = bougies[k];
          if (b.low <= hival && b.high >= loval) {
            if (k - lastHit >= 6) {
              hits++;
              lastHit = k;
            }
          }
          if (b.close < loval) {
            estCassee = true;
            dateFin = b.time;
            break;
          }
        }

        if (estCassee && supprimerZonesCassees) continue;
        if (hits === 0 && !afficherNonRetestees) continue;
        if (estFaible && !afficherFaibles) continue;
        if (hits < minRetests) continue;

        const force = hits > 3 ? 'PROVEN' : (hits >= 1 ? 'VERIFIED' : (estFaible ? 'WEAK' : 'UNTESTED'));
        candidates.push({
          id: 'shved-sup-' + i,
          type: 'SUPPORT',
          prixHaut: hival,
          prixBas: loval,
          prixMedian: (hival + loval) / 2,
          retests: hits,
          force: force,
          dateDebut: bougies[i].time,
          dateFin: dateFin
        });
      }
    }

    let finales = candidates;
    if (zoneMerge && candidates.length > 1) {
      const fusionnees = [];
      const traitees = new Set();
      for (let a = 0; a < candidates.length; a++) {
        const zA = candidates[a];
        if (traitees.has(zA.id)) continue;
        let hi = zA.prixHaut;
        let lo = zA.prixBas;
        let totalHits = zA.retests;
        let force = zA.force;
        traitees.add(zA.id);

        for (let b = a + 1; b < candidates.length; b++) {
          const zB = candidates[b];
          if (traitees.has(zB.id) || zA.type !== zB.type) continue;
          if ((hi >= zB.prixBas && hi <= zB.prixHaut) || (lo <= zB.prixHaut && lo >= zB.prixBas)) {
            hi = Math.max(hi, zB.prixHaut);
            lo = Math.min(lo, zB.prixBas);
            totalHits += zB.retests;
            traitees.add(zB.id);
            if (totalHits > 3) force = 'PROVEN';
            else if (totalHits >= 1) force = 'VERIFIED';
          }
        }
        fusionnees.push({
          ...zA,
          prixHaut: hi,
          prixBas: lo,
          prixMedian: (hi + lo) / 2,
          retests: totalHits,
          force: force
        });
      }
      finales = fusionnees;
    }

    const boites = [];
    const lignes = [];
    const labels = [];

    for (const z of finales) {
      const estSup = z.type === 'SUPPORT';
      const colBorder = estSup ? '#10b981' : '#ef4444';
      const colBg = estSup
        ? (z.force === 'PROVEN' ? 'rgba(16, 185, 129, 0.22)' : 'rgba(16, 185, 129, 0.12)')
        : (z.force === 'PROVEN' ? 'rgba(239, 68, 68, 0.22)' : 'rgba(239, 68, 68, 0.12)');

      const badge = z.force === 'PROVEN' ? '⭐ Prouvé' : (z.force === 'VERIFIED' ? '✓ Vérifié' : '⏳ Non retesté');
      const tag = estSup ? '🛡️ SSL Demand' : '🧱 BSL Supply';
      const lbl = tag + ' [' + z.retests + 'x] (' + badge + ')';

      if (afficherZones) {
        boites.push({
          id: 'box-' + z.id,
          prixHaut: z.prixHaut,
          prixBas: z.prixBas,
          dateDebut: z.dateDebut,
          dateFin: z.dateFin,
          couleurFond: colBg,
          couleurBordure: colBorder,
          label: lbl
        });
      }
      if (afficherLignes) {
        lignes.push({
          id: 'line-' + z.id,
          prix: z.prixMedian,
          dateDebut: z.dateDebut,
          dateFin: z.dateFin,
          couleur: colBorder,
          style: z.force === 'PROVEN' ? 'solid' : 'dashed',
          label: (estSup ? 'Support' : 'Résistance') + ' (' + z.prixMedian.toFixed(4) + ')'
        });
      }
      if (afficherEtiquettes) {
        labels.push({
          id: 'lbl-' + z.id,
          prix: estSup ? z.prixBas : z.prixHaut,
          date: z.dateDebut,
          texte: lbl,
          couleur: colBorder,
          position: estSup ? 'below' : 'above'
        });
      }
    }

    return {
      donnees: {
        supports: finales.filter(z => z.type === 'SUPPORT'),
        resistances: finales.filter(z => z.type === 'RESISTANCE'),
        totalZones: finales.length
      },
      primitives: { boites, lignes, labels },
      typeSpecial: 'shved-supply-demand'
    };
  }
};
